// init reads the dates of the catalog into the time fields, so the list can
// be sorted by the last episode.
func init() {
	for index := range Catalog {
		format := &Catalog[index]
		if format.LastEpisode == "" {
			continue
		}
		moment, err := time.Parse("2006-01-02", format.LastEpisode)
		if err != nil {
			continue
		}
		format.LastEpisodeTime = moment
	}
}
